-- migrate:up
-- Reflections: replace the abstract question catalogue with a functional one.
--
-- WHY. `ci.questions` held 715 rows, 709 of them generated by an LLM with no
-- curation. They were essays, not questions a memory system can answer:
--   "What does 'failure' mean to you, and how do you cope with it?"
--   "What is a fundamental belief you hold about the world?"
--   "How important is shared history versus shared current interests ...?"
-- Nothing in a person's imported data can settle any of those, which is why
-- only 20 of 715 had ever been answered (2.8%) and 15 of those 20 were
-- machine-inferred. Seventeen rows even ended in a stray import artefact
-- (" 10", " 14"), and the 18 categories ranged from 72 rows down to 1.
--
-- WHAT REPLACES IT. 1273 curated questions over exactly 8 life categories,
-- weighted toward the functional end — the kind a form or a friend asks, that
-- a person answers in a sentence and that the appliance can often infer from
-- data it already holds:
--   factual      742   one stable, verifiable fact ("What is your blood type?")
--   preference   403   a taste or habitual choice ("Window or aisle?")
--   narrative    128   a short story, anchored to something concrete
--
-- The tier is not decoration: `answer_tier` exists so the product can ask the
-- functional questions FIRST and leave the reflective ones until it has earned
-- them. Ordering by tier is the whole point of recording it.
--
-- NOTHING IS DELETED. `ci.answers` and `ci.feed_queue` both carry an
-- ON DELETE CASCADE foreign key to `ci.questions`, so deleting a retired
-- question would silently take a real human answer with it. Retired rows are
-- deactivated (`is_active = false`) instead, and any question that already has
-- an answer stays ACTIVE regardless of how abstract it is — a question someone
-- actually answered has earned its place.
--
-- Idempotent: re-running deactivates nothing new, re-cleans nothing, and
-- inserts nothing (the seed insert is guarded by a NOT EXISTS on question_text).

-- 1. Record which tier a question belongs to.
ALTER TABLE ci.questions
  ADD COLUMN IF NOT EXISTS answer_tier text;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint WHERE conname = 'questions_answer_tier_check'
  ) THEN
    ALTER TABLE ci.questions
      ADD CONSTRAINT questions_answer_tier_check
      CHECK (answer_tier IS NULL OR answer_tier IN ('factual','preference','narrative'));
  END IF;
END $$;

CREATE INDEX IF NOT EXISTS questions_tier_idx
  ON ci.questions (answer_tier) WHERE is_active = true;

-- 2. Repair the trailing-digit import artefact on any row we are keeping.
--    Anchored to a trailing space + 1-3 digits, which no legitimate question
--    ends with; a question ending in a year ("...in 2024?") ends with '?' and
--    is therefore untouched.
UPDATE ci.questions
   SET question_text = regexp_replace(question_text, '\s+[0-9]{1,3}\s*$', ''),
       updated_at    = now()
 WHERE question_text ~ '\s[0-9]{1,3}\s*$';

-- 3. Retire the un-answered legacy catalogue. A question with an answer stays.
UPDATE ci.questions q
   SET is_active  = false,
       updated_at = now()
 WHERE q.is_active
   AND q.created_by_llm
   AND NOT q.is_seed_question
   AND NOT EXISTS (SELECT 1 FROM ci.answers a WHERE a.question_id = q.question_id)
   AND NOT EXISTS (SELECT 1 FROM ci.feed_queue f WHERE f.question_id = q.question_id);

-- 4. Fold the 18 ad-hoc categories into the 8 that survive, for whatever rows
--    remain active (i.e. the ones somebody answered).
UPDATE ci.questions SET question_category = CASE question_category
    WHEN 'Core Identity'             THEN 'Identity & Background'
    WHEN 'Life History & Background' THEN 'Identity & Background'
    WHEN 'Culture'                   THEN 'Identity & Background'
    WHEN 'Autonomy'                  THEN 'Identity & Background'
    WHEN 'Personal Preferences'      THEN 'Preferences & Favorites'
    WHEN 'Favorites & Dislikes'      THEN 'Preferences & Favorites'
    WHEN 'Physical Health'           THEN 'Health & Body'
    WHEN 'Mental Wellbeing'          THEN 'Health & Body'
    WHEN 'Family Life'               THEN 'Relationships & People'
    WHEN 'Friendships & Social'      THEN 'Relationships & People'
    WHEN 'Daily Life & Routines'     THEN 'Home & Daily Life'
    WHEN 'Schedule'                  THEN 'Home & Daily Life'
    WHEN 'Home'                      THEN 'Home & Daily Life'
    WHEN 'Career & Professional'     THEN 'Work & Money'
    WHEN 'Places & Travel'           THEN 'Places & Travel'
    WHEN 'Hobbies & Leisure'         THEN 'Interests & Culture'
    WHEN 'Entertainment & Media'     THEN 'Interests & Culture'
    WHEN 'Highs & Lows'              THEN 'Interests & Culture'
    ELSE question_category
  END,
  updated_at = now()
 WHERE question_category IS NOT NULL;

-- 5. The catalogue. Guarded per row on question_text so a re-run is a no-op and
--    so a seed question that duplicates a surviving legacy one is skipped
--    rather than creating a near-duplicate pair.
INSERT INTO ci.questions
