-- migrate:down
-- Remove only what this migration added, and only if it is still untouched:
-- a seed question somebody has since answered is left alone.
DELETE FROM ci.questions q
 WHERE q.is_seed_question
   AND NOT q.created_by_llm
   AND NOT EXISTS (SELECT 1 FROM ci.answers a WHERE a.question_id = q.question_id)
   AND NOT EXISTS (SELECT 1 FROM ci.feed_queue f WHERE f.question_id = q.question_id);

DROP INDEX IF EXISTS ci.questions_tier_idx;
ALTER TABLE ci.questions DROP CONSTRAINT IF EXISTS questions_answer_tier_check;
ALTER TABLE ci.questions DROP COLUMN IF EXISTS answer_tier;
-- The deactivation in step 3 and the category fold in step 4 are NOT reversed:
-- nothing here records which rows were already inactive or which category a row
-- previously had, so "restoring" them would be a guess that re-activates 709
-- abstract questions the product deliberately retired.
